/* SPDX-License-Identifier: GPL-2.0-only */
#define _POSIX_C_SOURCE 200809L
#include "watchdog_owner.h"
#include <fcntl.h>
#include <linux/watchdog.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <time.h>
#define QW_PHASE_NS UINT64_C(2000000000)

void qw_owner_fail(struct qw_owner *o)
{if(o)o->state=QW_HOLD;}
static int fail(struct qw_owner *o)
{qw_owner_fail(o);return -1;}
static int clock_read(struct qw_owner *o,uint64_t *now)
{
 struct timespec t;
 if(clock_gettime(CLOCK_MONOTONIC,&t)||t.tv_sec<0||t.tv_nsec<0||t.tv_nsec>=1000000000L||
    (uint64_t)t.tv_sec>(UINT64_MAX-(uint64_t)t.tv_nsec)/UINT64_C(1000000000))return fail(o);
 *now=(uint64_t)t.tv_sec*UINT64_C(1000000000)+(uint64_t)t.tv_nsec;
 if(*now==UINT64_MAX||*now<o->last_ns)return fail(o);
 o->last_ns=*now;return 0;
}
static int descriptor(struct qw_owner *o)
{
 struct stat st;
 if(o->fd<3)return fail(o);
 int flags=fcntl(o->fd,F_GETFL),fdflags=fcntl(o->fd,F_GETFD);
 if(flags<0||fdflags<0||fstat(o->fd,&st)||(flags&O_ACCMODE)!=O_WRONLY||
    !(fdflags&FD_CLOEXEC)||!S_ISCHR(st.st_mode)||st.st_rdev!=o->device||
    st.st_dev!=o->node_filesystem||st.st_ino!=o->node_inode)return fail(o);
 return 0;
}
int qw_owner_take(struct qw_owner *o,int *slot,dev_t device)
{
 if(!o||!slot||!device||o->fd!=-1||o->state!=QW_EMPTY||*slot<3)return -1;
 struct stat st;
 int flags=fcntl(*slot,F_GETFL),fdflags=fcntl(*slot,F_GETFD);
 if(flags<0||fdflags<0||fstat(*slot,&st)||(flags&O_ACCMODE)!=O_WRONLY||
    !(fdflags&FD_CLOEXEC)||!S_ISCHR(st.st_mode)||st.st_rdev!=device)return -1;
 *o=(struct qw_owner){.fd=*slot,.state=QW_UNKNOWN,.device=device,
  .node_filesystem=st.st_dev,.node_inode=st.st_ino};
 *slot=-1;return 0;
}
int qw_owner_check(struct qw_owner *o)
{
 if(!o||o->state==QW_HOLD)return -1;
 if(o->state!=QW_ENABLING&&o->state!=QW_ACTIVE5)return fail(o);
 uint64_t now;
 if(clock_read(o,&now)||now<o->start_ns||now-o->start_ns>=QW_PHASE_NS||
    now>=o->session_deadline_ns)return fail(o);
 if(descriptor(o))return -1;
 /* Metadata syscalls consume the SAME phase budget; re-read immediately before
  * a caller may service the watchdog, not just before descriptor inspection. */
 if(clock_read(o,&now)||now<o->start_ns||now-o->start_ns>=QW_PHASE_NS||
    now>=o->session_deadline_ns)return fail(o);
 return 0;
}
static int control(struct qw_owner *o,unsigned long command,int *value)
{
 if(qw_owner_check(o))return -1;
 if(ioctl(o->fd,command,value))return fail(o);
 return qw_owner_check(o);
}
int qw_owner_begin(struct qw_owner *o,uint64_t source_start,enum qw_phase phase,uint64_t session_deadline)
{
 if(!o||o->state==QW_HOLD)return -1;
 if((o->state!=QW_UNKNOWN&&o->state!=QW_DISABLED)||
    source_start==UINT64_MAX||session_deadline==UINT64_MAX||session_deadline<=source_start||
    (phase!=QW_NEXT&&phase!=QW_RETIRE))return fail(o);
 o->start_ns=source_start;o->session_deadline_ns=session_deadline;
 o->phase=phase;o->capture_progress=0;o->state=QW_ENABLING;
 int timeout=5,option=WDIOS_ENABLECARD;
 /* SETTIMEOUT may itself ping/start inherited active hardware. Mark transition
  * unknown before the FIRST effect; do not service if phase/clock already bad. */
 if(control(o,WDIOC_SETTIMEOUT,&timeout)||timeout!=5)return fail(o);
 if(control(o,WDIOC_SETOPTIONS,&option))return -1;
 timeout=0;
 if(control(o,WDIOC_GETTIMEOUT,&timeout)||timeout!=5)return fail(o);
 o->state=QW_ACTIVE5;return 0;
}
int qw_owner_capture_progress(struct qw_owner *o)
{
 if(!o||o->state==QW_HOLD)return -1;
 if(o->state!=QW_ACTIVE5||o->phase!=QW_NEXT||o->capture_progress)return fail(o);
 int ignored=0;
 if(control(o,WDIOC_KEEPALIVE,&ignored))return -1;
 o->capture_progress=1;return 0;
}
int qw_owner_disable_boundary(struct qw_owner *o)
{
 if(!o||o->state==QW_HOLD)return -1;
 if(o->state!=QW_ACTIVE5||(o->phase==QW_NEXT&&!o->capture_progress))return fail(o);
 int option=WDIOS_DISABLECARD;
 /* Failure/time loss after the syscall leaves UNKNOWN hardware state; do NOT
  * re-enable, ping, V-close or claim the retained FD guarantees recovery. */
 if(control(o,WDIOC_SETOPTIONS,&option))return -1;
 o->state=QW_DISABLED;return 0;
}
int qw_owner_idle_observe(struct qw_owner *o)
{
 if(!o||o->state==QW_HOLD)return -1;
 if(o->state!=QW_DISABLED)return fail(o);
 uint64_t now;
 if(clock_read(o,&now))return -1;
 if(descriptor(o))return -1;
 return clock_read(o,&now);
}
int qw_owner_give_back(struct qw_owner *o,int *slot)
{
 if(!o||!slot||*slot!=-1)return -1;
 if(qw_owner_idle_observe(o))return -1;
 *slot=o->fd;*o=(struct qw_owner)QW_OWNER_EMPTY;return 0;
}

/* SPDX-License-Identifier: GPL-2.0-only */
#ifndef QC_WATCHDOG_OWNER_H
#define QC_WATCHDOG_OWNER_H
#include <stdint.h>
#include <sys/types.h>
enum qw_state {QW_EMPTY,QW_UNKNOWN,QW_ENABLING,QW_ACTIVE5,QW_DISABLED,QW_HOLD};
enum qw_phase {QW_NEXT=1,QW_RETIRE=2};
struct qw_owner {
 int fd;
 enum qw_state state;
 enum qw_phase phase;
 dev_t device,node_filesystem;
 ino_t node_inode;
 uint64_t last_ns,start_ns,session_deadline_ns;
 unsigned capture_progress;
};
#define QW_OWNER_EMPTY { .fd=-1 }
/* Trusted exact driver/core/image and sole open-description custody, no aliases,
 * concurrent I/O/fd-table changes/reentry. Static fresh/disjoint objects only.
 * Preopen already STARTS hardware. Move metadata-only take leaves UNKNOWN, never
 * armed proof. No actor opens/duplicates/closes here. Source associations and
 * original provider/backing admission are NOT proved by descriptor metadata. */
int qw_owner_take(struct qw_owner *,int *,dev_t);
int qw_owner_begin(struct qw_owner *,uint64_t,enum qw_phase,uint64_t);
int qw_owner_check(struct qw_owner *); /* active phase, real clock, <2s */
/* ONLY exact producer callsite after full raw CRC/extent/status and ACTIVE keyed
 * receipt/sequence checks. At most once per NEXT; not a generic feeder API. */
int qw_owner_capture_progress(struct qw_owner *);
/* Trusted integration calls ONLY after real successful producer/postchecks or
 * normal END/QUERY/ACK and cleanup. No caller-supplied 'qualified' Boolean.
 * DISABLED is ioctl ACK/logical state only, not electrical/DMA stop proof. */
int qw_owner_disable_boundary(struct qw_owner *);
int qw_owner_idle_observe(struct qw_owner *); /* DISABLED; no servicing */
int qw_owner_give_back(struct qw_owner *,int *); /* DISABLED custody move, no close */
void qw_owner_fail(struct qw_owner *); /* sticky HOLD, no IO, no armed guarantee */
/* No reset/close/destructor/HOLD-clear/retry/periodic thread or timer. On failure
 * actual FD stays owned, unless caller violates trusted custody. Failed disable
 * may already have stopped it; HOLD NEVER guarantees armed recovery. Final close
 * is outside this API; Linux close error cannot preserve an actual description
 * merely by retaining its former numeric FD or retrying it. Nominal5s unchanged. */
#endif

/* SPDX-License-Identifier: GPL-2.0-only
 * Included AFTER the actual frozen native adapter bodies (renamed _legacy).
 * One real singleton/context, no synthetic producer or success callbacks.
 */
#include "native_watchdog.h"
static unsigned native_initialized;
static int native_guard_failure(void)
{nh_native_fence(NULL);return CAMERA_IO_ERROR;}

void nh_native_init(void)
{
 if(native_initialized){(void)native_guard_failure();return;}
 native_init_legacy();native_initialized=1;
}
int nh_native_watchdog_take(int *slot,dev_t device)
{
 if(!native_initialized||native.retirement_uncertain||source_clock.failed||
    native.continuous_sensor!=-1||native.continuous_frame!=-1||native.h264_stream_fd!=-1||
    native.encoder_hold!=-1||native.produced_storage||native.resident_storage||
    parked_after_stop||memory_state.ledger.initialized)return CAMERA_NOT_READY;
 return qw_owner_take(&native.watchdog,slot,device)?CAMERA_NOT_READY:CAMERA_OK;
}
static int native_guard_begin(enum qw_phase phase)
{
 if(native_initialized&&(stop||native.retirement_uncertain||source_clock.failed))
  return native_guard_failure();
 if(!native_initialized||native.watchdog.fd<3||
    native.watchdog.state==QW_EMPTY||native.watchdog.state==QW_HOLD)
  return CAMERA_NOT_READY;
 uint64_t start=nh_native_now(NULL);
 if(start==UINT64_MAX||!memory_state.ledger.initialized||
    memory_state.session_start>UINT64_MAX-NH_SESSION_NS||
    start<memory_state.session_start||start-memory_state.session_start>=NH_SESSION_NS)
  return native_guard_failure();
 if(qw_owner_begin(&native.watchdog,start,phase,memory_state.session_start+NH_SESSION_NS))
  return native_guard_failure();
 return CAMERA_OK;
}
int nh_native_next(void *context,struct camera_packet *packet,struct nh_key *key)
{
 if(!packet||!key)return CAMERA_INVALID;
 /* No lifetime open/query, malloc, sensor/config/capture or codec effect until
  * actual owned guard and original preparation/paid-buffer prerequisites exist. */
 if(!sensor_baseline_requested||!storage_selected||!memory_state.ledger.initialized||
    !memory_state.ledger.paid[0]||!memory_state.ledger.paid[1])return CAMERA_NOT_READY;
 int result=native_guard_begin(QW_NEXT);if(result)return result;
 result=native_next_legacy(context,packet,key);
 /* The real legacy body includes BOTH lifetime calls, cancellation/receipt and
  * encoded-begin<2s checks. Its earlier inner guard closes have been removed. */
 if(result||native.retirement_uncertain||source_clock.failed||
    qw_owner_disable_boundary(&native.watchdog)){
  memset(packet,0,sizeof(*packet));memset(key,0,sizeof(*key));
  return native_guard_failure(); /* actual unreturned backing/FDs retained */
 }
 return CAMERA_OK;
}
int nh_native_release(void *context,const struct camera_packet *packet)
{
 if(!packet||!native_initialized||native.retirement_uncertain||source_clock.failed||
    qw_owner_idle_observe(&native.watchdog))return native_guard_failure();
 int result=native_release_legacy(context,packet);
 return result?native_guard_failure():CAMERA_OK;
}
static void native_retired_cpu_release(void)
{
 /* Called ONLY after original normal retirement and successful logical guard
  * disable. A failed disable keeps resident/parked backing in the actual owner. */
 if(native.resident_storage!=raw)free(native.resident_storage);
 native.resident_storage=NULL;parked_after_stop=NULL;memset(&expected,0,sizeof(expected));
}
int nh_native_retire(void *context)
{
 if(native.produced_storage)return CAMERA_BUSY; /* known held CPU loan, no effect */
 int result=native_guard_begin(QW_RETIRE);if(result)return result;
 result=native_retire_body(context);
 if(result||native.retirement_uncertain||source_clock.failed||
    qw_owner_disable_boundary(&native.watchdog))return native_guard_failure();
 native_retired_cpu_release();
 return CAMERA_OK;
}
int nh_native_retire_held(void *context,const struct camera_packet *packet)
{
 if(native.retirement_uncertain||source_clock.failed||parked_after_stop)return native_guard_failure();
 if(packet){
  if(!native.produced_storage||packet->data!=expected.data||packet->bytes!=expected.bytes||
     packet->monotonic_ns!=expected.monotonic_ns)return native_guard_failure();
 }else if(native.produced_storage)return native_guard_failure();
 int result=native_guard_begin(QW_RETIRE);if(result)return result;
 result=native_retire_held_legacy(context,packet);
 if(result||native.retirement_uncertain||source_clock.failed||
    qw_owner_disable_boundary(&native.watchdog))return native_guard_failure();
 native_retired_cpu_release();
 return CAMERA_OK;
}
int nh_native_watchdog_give_back(int *slot)
{
 if(!native_initialized||native.retirement_uncertain||source_clock.failed||
    native.receipt_armed||native.continuous_frame!=-1||native.continuous_sensor!=-1||
    native.h264_stream_fd!=-1||native.encoder_hold!=-1||native.produced_storage||
    native.resident_storage||parked_after_stop||native.close_unknown)return CAMERA_NOT_READY;
 return qw_owner_give_back(&native.watchdog,slot)?CAMERA_NOT_READY:CAMERA_OK;
}

/* SPDX-License-Identifier: GPL-2.0-only */
#ifndef QC_NATIVE_WATCHDOG_OWNER_H
#define QC_NATIVE_WATCHDOG_OWNER_H
#include <sys/types.h>
#include "native_adapter.h"
/* Fresh singleton init -> take UNKNOWN actual preopened watchdog -> old explicit
 * storage/exact139/memory preparation -> bounded next/release/normal retire.
 * Opening occurred elsewhere and is already an effect. Sole actual description,
 * no aliases or external operations; exact core/driver/image/current recovery and
 * provider/backing admission remain trusted prerequisites, NOT metadata proof.
 * No native acceptance or permission to call any old allocation/capture helper.
 */
int nh_native_watchdog_take(int *bootstrap_slot,dev_t expected_device);
/* Only after successful logical disable + known local source normal retirement,
 * no source/codec FDs/loans/resident backing left. Custody move, not final close,
 * electrical stop, DMA proof or permission to dispose other owned resources. */
int nh_native_watchdog_give_back(int *recipient_slot);
#endif

/* SPDX-License-Identifier: GPL-2.0-only
 * Provider close AFTER original retirement proof, not a watchdog close API.
 */
static int source_close_once(struct qc_rtsp_context *c,int *slot)
{
 if(!slot||*slot<0||slot==&c->watchdog.fd)return capture_failed(c);
 if(qw_owner_check(&c->watchdog))return capture_failed(c); /* keep actual FD */
 int attempted=*slot;
 *slot=-1; /* Linux can consume the FD even when close returns an error. */
 if(close(attempted)){
  c->last_close_attempt=attempted;c->close_unknown=1;
  return capture_failed(c); /* diagnostic number, NOT an owned description */
 }
 return CAMERA_OK;
}

/* SPDX-License-Identifier: GPL-2.0-only
 * Controlled rtspd source import is generated and diffed by build.py.
 * No JPEG, fixture-file, network, parser, SDK or software codec dependency.
 */
#include "native_adapter.h"
#include "sensor_baseline.h"
#include "memory_runtime.h"
#include "rtspd-native-import.c"
#include <sys/resource.h>
static struct qc_rtsp_context native;
static uint8_t parameters[256];
static struct camera_packet expected;
static uint8_t *parked_after_stop;
static struct nh_memory_runtime memory_state;
static uint64_t codec_live_bytes;
static unsigned storage_selected,raw_reuse_requested;
static int native_guard_present(void)
{return !stop&&!native.retirement_uncertain&&!source_clock.failed&&native.watchdog.fd>=3&&
 (native.watchdog.state==QW_UNKNOWN||native.watchdog.state==QW_DISABLED||native.watchdog.state==QW_ACTIVE5);}
static int prepare_output(struct qc_rtsp_context *c,uint64_t begin)
{
 int forecast=nh_memory_runtime_gate(&memory_state,NH_MEM_PRE_NEXT,begin);
 if(forecast){if(forecast==NH_MEM_CLOCK)native.retirement_uncertain=1;return CAMERA_NOT_READY;}
 if(qw_owner_check(&c->watchdog)){nh_native_fence(NULL);return CAMERA_IO_ERROR;}
 if(c->resident_storage)return CAMERA_OK;
 if(!memory_state.ledger.initialized)return CAMERA_NOT_READY;
 if(raw_reuse_requested){c->resident_storage=raw;return CAMERA_OK;} /* already-owned/paid raw pages, NEVER credit twice */
 c->resident_storage=malloc(1048576);if(!c->resident_storage)return CAMERA_NOT_READY;
 int reason=nh_memory_prefault_owned(&memory_state,2,c->resident_storage,1048576,begin);
 if(!reason)reason=nh_memory_runtime_gate(&memory_state,NH_MEM_PRE_NEXT,begin);
 if(reason){if(reason==NH_MEM_CLOCK)native.retirement_uncertain=1;return CAMERA_NOT_READY;}
 return CAMERA_OK;
}
static int before_encode_gate(uint64_t begin)
{
 int result=nh_memory_runtime_gate(&memory_state,NH_MEM_PRE_NEXT,begin);
 if(result==NH_MEM_CLOCK)native.retirement_uncertain=1;
 return result?CAMERA_NOT_READY:CAMERA_OK;
}
_Static_assert(sizeof(struct qc_capture_receipt)==56,"receipt ABI");
_Static_assert(sizeof(struct qc_hwenc_lifetime)==56,"kernel75 lifetime ABI");
static int lifetime(void)
{
 struct qc_hwenc_lifetime q={0};
 if(native.h264_stream_fd<0)native.h264_stream_fd=open("/dev/qc07f-encoder",O_RDWR);
 if(native.h264_stream_fd<0||ioctl(native.h264_stream_fd,QC_HWENC_LIFETIME_QUERY,&q)||
    q.version!=1||q.struct_bytes!=sizeof(q)||q.reserved||q.quarantined||q.dma_uncertain||
    q.guard_poisoned||q.failed_reset_step||q.reset_error||q.fault_session||!q.session_sequence){
  native.retirement_uncertain=1;return CAMERA_IO_ERROR;
 }
 fprintf(stderr,"NH_CODEC_LIFETIME session_sequence=%llu live_bytes=%llu healthy=1\n",
 (unsigned long long)q.session_sequence,(unsigned long long)q.live_bytes);
 codec_live_bytes=q.live_bytes;
 return CAMERA_OK;
}
static void native_init_legacy(void)
{source_context_init(&native);memset(&source_clock,0,sizeof(source_clock));sensor_baseline_requested=0;memset(&sensor_baseline_report,0,sizeof(sensor_baseline_report));memset(&memory_state,0,sizeof(memory_state));codec_live_bytes=0;storage_selected=0;raw_reuse_requested=0;}
int nh_native_storage_select(const char *mode)
{
 if(!mode||storage_selected||memory_state.ledger.initialized||native.continuous_frame>=0||native.h264_stream_fd>=0)return CAMERA_NOT_READY;
 if(!strcmp(mode,"raw-reuse-k75"))raw_reuse_requested=1;
 else if(strcmp(mode,"separate"))return CAMERA_INVALID;
 storage_selected=1;return CAMERA_OK;
}
int nh_native_optin_exact139(void)
{
 if(native.retirement_uncertain||native.continuous_frame>=0||native.continuous_sensor>=0||native.h264_stream_fd>=0||sensor_baseline_requested)return CAMERA_NOT_READY;
 sensor_baseline_requested=1;return CAMERA_OK;
}
void nh_native_sensor_report(void){nh_sensor_log(&sensor_baseline_report);}
int nh_native_memory_start(uint64_t start)
{
 if(!native_guard_present())return CAMERA_NOT_READY;
 if(!storage_selected)return CAMERA_NOT_READY;
 int r=nh_memory_runtime_init(&memory_state,start,nh_native_now,nh_native_cancelled,NULL,raw_reuse_requested);
 if(!r)r=nh_memory_runtime_gate(&memory_state,NH_MEM_INITIAL,start);
 if(r==NH_MEM_CLOCK)native.retirement_uncertain=1;
 return r?CAMERA_NOT_READY:CAMERA_OK;
}
int nh_native_memory_fixed_buffers(void *hub)
{
 if(!native_guard_present())return CAMERA_NOT_READY;
 uint64_t begin=nh_native_now(NULL);int r=nh_memory_runtime_gate(&memory_state,NH_MEM_FIXED_PAID,begin);
 if(!r)r=nh_memory_prefault_owned(&memory_state,0,raw,sizeof(raw),begin);
 if(!r)r=nh_memory_runtime_gate(&memory_state,NH_MEM_FIXED_PAID,begin);
 if(!r)r=nh_memory_prefault_owned(&memory_state,1,hub,1048576,begin);
 if(!r)r=nh_memory_runtime_gate(&memory_state,NH_MEM_FIXED_PAID,begin);
 if(r==NH_MEM_CLOCK)native.retirement_uncertain=1;
 return r?CAMERA_NOT_READY:CAMERA_OK;
}
int nh_native_memory_gate(void *unused,enum nh_memory_stage stage)
{
 if(!native_guard_present())return CAMERA_NOT_READY;
 (void)unused;if(!memory_state.ledger.initialized)return CAMERA_NOT_READY;
 if(stage==NH_MEM_POST_FIRST&&nh_memory_credit_codec(&memory_state.ledger,codec_live_bytes,!native.retirement_uncertain&&!source_clock.failed))return CAMERA_NOT_READY;
 uint64_t begin=nh_native_now(NULL);int r=nh_memory_runtime_gate(&memory_state,stage,begin);
 if(r==NH_MEM_CLOCK)native.retirement_uncertain=1;
 return r?CAMERA_NOT_READY:CAMERA_OK;
}
void nh_native_memory_report(void){nh_memory_log(&memory_state);}
void nh_native_cancel(int sig){on_signal(sig);}
uint64_t nh_native_now(void *unused)
{
 (void)unused;uint64_t now=producer_clock_ns(NULL);
 if(now==UINT64_MAX){native.retirement_uncertain=1;qw_owner_fail(&native.watchdog);}
 return now;
}
int nh_native_cancelled(void *unused)
{
 (void)unused;
 if(stop||native.retirement_uncertain)return 1;
 if(native.receipt_armed){
  struct qc_capture_receipt proof;
  if(qc_receipt_query(native.continuous_frame,&native.receipt_key,&proof)||
     proof.state!=QC_RECEIPT_ACTIVE||proof.reason||proof.stop_result||proof.stopped_ns){
   native.retirement_uncertain=1;return 1;
  }
  native.receipt_evidence=proof;
 }
 return 0;
}
static int native_next_legacy(void *unused,struct camera_packet *p,struct nh_key *key)
{
 (void)unused;
 if(stop)return CAMERA_DISCONNECTED;
 if(!sensor_baseline_requested)return CAMERA_NOT_READY; /* no silent table preparation */
 if(native.retirement_uncertain)return CAMERA_IO_ERROR;
 if(lifetime())return CAMERA_IO_ERROR; /* reject receipt-less/legacy codec ABI before capture */
 int r=produce_h264_frame(&native,0,p);if(r)return r;
 if(lifetime())return CAMERA_IO_ERROR;
 if(nh_native_cancelled(NULL))return CAMERA_IO_ERROR;
 if(native.produced_timing.encoded-native.produced_timing.begin>=2000){native.retirement_uncertain=1;return CAMERA_IO_ERROR;}
  *key=(struct nh_key){native.receipt_key.source_instance,native.receipt_key.file_instance,
                     native.receipt_key.generation,native.capture_sequence,native.produced_nal_crc32_bzip2};
 expected=*p;return CAMERA_OK;
}
static int native_release_legacy(void *unused,const struct camera_packet *p)
{
 (void)unused;
 if(native.retirement_uncertain||!native.produced_storage||p->data!=expected.data||
    p->bytes!=expected.bytes||p->monotonic_ns!=expected.monotonic_ns)return CAMERA_IO_ERROR;
 release_h264_frame(&native,p);memset(&expected,0,sizeof(expected));return CAMERA_OK;
}
static int native_retire_body(void *unused)
{
 (void)unused;int r=idle_h264_checked(&native);
 fprintf(stderr,"NH_NATIVE_RETIRE result=%d source=%llu file=%llu generation=%llu state=%u reason=%u stop_result=%d stopped_ns=%llu armed=%u uncertain=%d\n",
 r,(unsigned long long)native.receipt_key.source_instance,(unsigned long long)native.receipt_key.file_instance,
 (unsigned long long)native.receipt_key.generation,native.receipt_evidence.state,native.receipt_evidence.reason,
 native.receipt_evidence.stop_result,(unsigned long long)native.receipt_evidence.stopped_ns,
 native.receipt_armed,native.retirement_uncertain);
 if(!r&&qw_owner_check(&native.watchdog)){nh_native_fence(NULL);return CAMERA_IO_ERROR;}
 /* Retain resident backing until outer logical watchdog-disable ACK. */
 return r;
}
static int native_retire_held_legacy(void *unused,const struct camera_packet *p)
{
 (void)unused;
 if(native.retirement_uncertain||source_clock.failed||parked_after_stop)return CAMERA_IO_ERROR;
 if(p){
